param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\assinatura-payment-brick-$Stamp"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Full([string]$Path) {
  Join-Path $Root ($Path -replace "/", "\")
}

function Backup-File([string]$Path) {
  $Source = Full $Path

  if (-not (Test-Path -LiteralPath $Source)) {
    return
  }

  $Destination = Join-Path $Backup ($Path -replace "/", "\")
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Write-Base64File(
  [string]$Path,
  [string]$Base64
) {
  $Target = Full $Path
  New-Item -ItemType Directory -Force -Path (Split-Path $Target -Parent) | Out-Null

  $Text = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String($Base64)
  )

  [IO.File]::WriteAllText(
    $Target,
    $Text.TrimEnd() + "`n",
    $Utf8
  )

  Write-Host "[OK] $Path" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()

if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

$Required = @(
  "lib/subscription-service.ts",
  "lib/mercado-pago.ts",
  "app/api/checkout/lead/route.ts",
  "app/api/assinatura/mercado-pago/route.ts"
)

foreach ($File in $Required) {
  if (-not (Test-Path -LiteralPath (Full $File))) {
    throw "Arquivo necessario nao encontrado: $File"
  }
}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - ASSINATURA COM PAYMENT BRICK" -ForegroundColor Cyan
Write-Host "Pix + credito + debito + renovacao automatica" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

$Targets = @(
  "lib/subscription-checkout-payment.ts",
  "app/api/assinatura/checkout/route.ts",
  "app/api/assinatura/checkout/status/route.ts",
  "app/api/assinatura/checkout/webhook/route.ts",
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx",
  "lib/subscription-service.ts",
  "app/api/checkout/lead/route.ts"
)

foreach ($Target in $Targets) {
  Backup-File $Target
}

$Files = @{
  "lib/subscription-checkout-payment.ts" = ""
  "app/api/assinatura/checkout/route.ts" = ""
  "app/api/assinatura/checkout/status/route.ts" = ""
  "app/api/assinatura/checkout/webhook/route.ts" = ""
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx" = ""
}

foreach ($Entry in $Files.GetEnumerator()) {
  Write-Base64File $Entry.Key $Entry.Value
}

$PatcherPath = Join-Path $Root ".orcaly-patch-assinatura-$Stamp.cjs"
$PatcherCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($PatcherPath, $PatcherCode, $Utf8)

try {
  Write-Host ""
  Write-Host "==> Ajustando servico de assinatura" -ForegroundColor Cyan

  & node $PatcherPath

  if ($LASTEXITCODE -ne 0) {
    throw "O patcher nao conseguiu concluir as alteracoes."
  }
} finally {
  Remove-Item -LiteralPath $PatcherPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Verificando variaveis sem mostrar valores" -ForegroundColor Cyan

$CheckPath = Join-Path $Root ".orcaly-check-assinatura-$Stamp.cjs"

$CheckCode = @'
const { loadEnvConfig } = require("@next/env");

loadEnvConfig(process.cwd(), true);

const names = [
  "MERCADO_PAGO_PLATFORM_ACCESS_TOKEN",
  "NEXT_PUBLIC_MERCADO_PAGO_PUBLIC_KEY",
  "MERCADO_PAGO_WEBHOOK_SECRET",
  "NEXT_PUBLIC_SUPABASE_URL",
  "SUPABASE_SERVICE_ROLE_KEY"
];

console.table(
  names.map((name) => {
    const value = String(process.env[name] || "").trim();

    return {
      variavel: name,
      configurada: Boolean(value),
      tamanho: value.length
    };
  })
);
'@

[IO.File]::WriteAllText($CheckPath, $CheckCode, $Utf8)

try {
  & node $CheckPath

  if ($LASTEXITCODE -ne 0) {
    throw "A verificacao das variaveis falhou."
  }
} finally {
  Remove-Item -LiteralPath $CheckPath -Force -ErrorAction SilentlyContinue
}

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Limpando cache do Next" -ForegroundColor Cyan
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build" -ForegroundColor Cyan

  & npm.cmd run build
  $BuildCode = $LASTEXITCODE

  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O build falhou. Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "ASSINATURA REDESENHADA" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Interface: Payment Brick oficial do Mercado Pago"
Write-Host "Pagamento avulso: Pix, credito e debito"
Write-Host "Pix: QR Code e codigo na propria pagina"
Write-Host "Renovacao automatica: cartao de credito"
Write-Host "Periodo gratuito no painel: removido"
Write-Host "Dados do cartao: processados pelo Mercado Pago"
Write-Host "Backup: $Backup"
